c(25, "§4.1 table (verbatim); §4.1; §4.2 table (verbatim); §4.2", "data-caveat", "Distribution (verbatim): " + table("## 4.1 The distribution", 0) + " — mean 1.714★, median 1★, 72.45% one-star vs public 4.355★; themes by band (verbatim): " + table("## 4.2 Themes by star band", 0) + " — 'the bands differ in kind, not degree': money taken 2% of 5★ → 57% of 1★, praise 89% → 4%; five-star reviews are short (65% under 60 chars) and half carry votes; the review gate is most visible in the middle bands.", "n/a", "mixed", "1★ 355 (72.45%); 5★ 54 (11.02%); public 4.355★", "none", "table", "generalisable", ["6756282701"], "", "")

c(26, "§4.3; §4.4; §4.5; §4.6", "data-caveat", "By band: 5★ (54) — 48 praise but 29 name no quality, 35 under 60 characters, 27 carry votes (50%), 5 have not used the app yet ('Excited to try this in the new year!'), one buyer gave 5★ to be seen — 'the reviews tend to show to 5 star reviews first so that's why I gave it 5 stars. don't download this app'; 4★ (13) — 11 praise, 5 requests, one review-gate complaint; 3★ (27) — mixed and billing-heavy, three describe the review gate ('Just needed to rate to unlock'), the one satisfied buyer is here; 2★ (41) — the highest defect share of any band (29%); 1★ (355) — money taken 57%, pre-use wall 33%, scam 29%, ad mismatch 26%, only 13 contain any praise; 290 of 355 (81.69%) describe paying before seeing or money taken.", "n/a", "mixed", "5★ not-yet-used 5; 2★ defect 29%; 1★ money 57%", "none", "table", "generalisable", ["6822135295", "7269202665", "6772040713", "7240052353", "7069536244", "7105962949"], "", "")

c(27, "§4.7 table (verbatim); §4.7", "data-caveat", "Rating-vs-text contradictions (verbatim): " + table("## 4.7 Rating-versus-text", 0) + " — 3 explicit; beyond them 5 five-star, 2 four-star and 4 three-star reviews say they have not used the app yet and 13 describe being made to rate it: 'some stars in this corpus were given before any experience of the product'.", "n/a", "mixed", "MISMATCH 3; not-yet-used 11; REVIEW_GATE 13", "none", "Emerging", "generalisable", ["7240052353", "7269202665", "7278892888"], "", "")

c(28, "§5.1 table (verbatim); §5.1; §5.2 table (verbatim); §5.2; §5.7", "data-caveat", "The monetisation model — a hard paywall at onboarding → a paid or card-gated trial → weekly / monthly / 3-month / yearly / lifetime plans → a half-price lifetime offer on a timer → content packs on top; from June 2021 web checkout billed by card or PayPal (verbatim): " + table("## 5.1 The monetisation model", 0) + " — of 182 buyers 93 (51.1%) report a post-purchase problem, 65 regret, 50 ask for a refund, 1 satisfied; segment rates (verbatim): " + table("## 5.2 Segment rates", 0) + " — by era: chose to pay 56 / 94 / 27 / 5; charged without choosing 2 / 6 / 35 / 2; by storefront: buyers US 98, UK 14, CA 9, AU 7; no conversion, fraud finding or refund estimate.", "n/a", "mixed", "PAID 182 (51.1% problem, 35.7% regret, 27.5% refund, 1 satisfied); CHARGED_NOT_CHOSEN 45; refunds 4", "none", "High-priority", "generalisable", ["6883817922", "7391062590"], "", "")

c(29, "§5.3; §5.4 table (verbatim); §5.4", "insight", "What buyers bought: 'lifetime' named in 58 of 182, a trial week 41, a year 17, a month 15 — lifetime is the plan most named. What triggers a purchase (verbatim): " + table("## 5.4 What triggers a purchase", 0) + " — the ad (52 of 72 misleading-ad reviewers paid: 'Nothing like the Facebook adds. Was so excited to purchase but left sorely disappointed'); the half-price lifetime offer (40 of 46 paid: 'It's originally FORTY so I went ahead and got it'); paying to see the app at all ('you have to pay to even access the app. Whatever, did that'); hope that more content sits behind the next payment ('thinking maybe I would see more checklists after I paid'); a free trial that billed (28 of 45); several blame themselves ('my own fault for not just trying it first'; 'My bad for purchasing the lifetime for $40').", "ad + countdown lifetime offer + pay-to-enter", "purchase-driver", "misleading-ad payers 52/72; countdown payers 40/46; paid-trial buyers 16; trial-billed 28/45", "dont", "High-priority", "generalisable", ["6817958869", "7088093804", "7062384160", "7084713878", "6793208836", "6950304754"], "", "the countdown lifetime offer converts 87% of those who mention it — and 13 of them were charged twice")

c(30, "§5.5", "must-never-break", "What goes wrong after purchase — among the 182 who chose to pay: an unwanted charge 51 (28.0%) — double 24, wrong plan 15, price mismatch 8; content still locked 30 (16.5%); no access at all 25 (13.7%); a support failure 43 (23.6%); scam language 50 (27.5%); among the 45 charged without choosing: a trial that billed 28 (62.2%), charged after cancelling 15, could not cancel 16, unauthorised 13, web checkout 8, support failure 18 (40.0%), bank action 5, refund received 3; the buyer's sequence: 'I also fell for the £19.99 offer… it is NOT telling me I have a lifetime membership but a WEEK membership… I would like a refund but seeing as the creator isn't responding to these reviews, I don't hold much hope'.", "n/a", "churn", "buyers: unwanted charge 28.0%, locked 16.5%, no access 13.7%, support failure 23.6%; charged-not-chosen: trial billed 62.2%, support failure 40.0%", "must-never-break", "High-priority", "generalisable", ["6883817922", "7197019939"], "", "")

c(31, "§5.6 table (verbatim); §5.6", "monetization", "Upgrade barriers among non-buyers (verbatim): " + table("## 5.6 Upgrade barriers", 0) + " — 97 (19.80%) hit the wall before any use and did not pay; no free trial 58; price 54; card details for a 'free' trial 8; would pay with a real trial, sync or lower price 8 — 'the barrier is the order of events, not the price alone: people were asked to pay before seeing anything, and many who paid then found little inside'.", "pay-first", "blocked-conversion", "wall-no-pay 97 / 19.80%; NO_FREE_TRIAL 58; PRICE 54; CARD 8; CONDITIONAL 8", "product-rule", "High-priority", "generalisable", ["6802711687", "7169002761", "6778875717", "6743042296", "6818850233"], "", "")

